      </svg>

      {/* Left Ribbon */}
      <div className="absolute left-0 top-[38%] -translate-y-1/2 w-[38vw] max-w-[480px] min-w-[240px] h-[300px] sm:h-[360px] animate-pulse">
        <svg viewBox="0 0 450 320" fill="none" className="w-full h-full overflow-visible">
